    if (bb == null || sb == null) {
        throw new IllegalArgumentException("ByteBuffer and StringBuilder cannot be null");
    }
    while (bb.hasRemaining()) {
        byte b = bb.get();
        if ((b & 0x80) == 0) {
            sb.append((char) b);
        } else {
            int length = 0;
            if ((b & 0xE0) == 0xC0) {
                length = 1;
            } else if ((b & 0xF0) == 0xE0) {
                length = 2;
            } else if ((b & 0xF8) == 0xF0) {
                length = 3;
            } else {
                throw new RuntimeException("Invalid UTF-8 start byte");
            }
            if (bb.remaining() < length) {
                throw new RuntimeException("Incomplete UTF-8 sequence");
            }
            int codePoint = b & ((1 << (7 - length)) - 1);
            for (int j = 0; j < length; j++) {
                b = bb.get();
                if ((b & 0xC0) != 0x80) {
                    throw new RuntimeException("Invalid UTF-8 continuance byte");
                }
                codePoint = (codePoint << 6) | (b & 0x3F);
            }
            sb.appendCodePoint(codePoint);
        }
        i++;
    }
    return i;
}
