import java.io.File;
import java.io.IOException;

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    FileDeleteHandler handler = new FileDeleteHandler(file);
    Runtime.getRuntime().addShutdownHook(new Thread(handler));
}

private static class FileDeleteHandler implements Runnable {
    private final File file;

    public FileDeleteHandler(File file) {
        this.file = file;
    }

    @Override
    public void run() {
        try {
            deleteFileOrDirectory(file);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void deleteFileOrDirectory(File file) throws IOException {
        if (file.isDirectory()) {
            File[] files = file.listFiles();
            if (files != null) {
                for (File fileToDelete : files) {
                    deleteFileOrDirectory(fileToDelete);
                }
            }
        }
        if (!file.delete()) {
            throw new IOException("Could not delete file: " + file.getAbsolutePath());
        }
    }
}
