import javax.swing.SwingUtilities;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class LogProcessor {
    private static final Logger LOG = Logger.getLogger(LogProcessor.class.getName());
    private static final LinkedBlockingQueue<LogRecord> logQueue = new LinkedBlockingQueue<>();
    private static final ExecutorService executor = Executors.newSingleThreadExecutor();

    static {
        executor.submit(() -> {
            while (true) {
                try {
                    LogRecord lr = logQueue.take();
                    SwingUtilities.invokeLater(() -> {
                        LogTable.addMessage(lr);
                    });
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return;
                }
            }
        });
    }

    /**
     * Add a log record message to be displayed in the LogTable. This method is thread-safe as it posts requests to the SwingThread rather than processing directly.
     */
    public static void addMessage(final LogRecord lr) {
        if (lr == null) {
            throw new IllegalArgumentException("LogRecord cannot be null");
        }
        logQueue.add(lr);
    }
}
