public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if target and resultMap are not null
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Both target graph and resultMap must not be null");
    }

    // Clear the target graph to start from scratch
    target.clear();

    // Get the keys from resultMap
    Set<String> keys = resultMap.keySet();

    // Create two sets to represent the two parts of the bipartite graph
    Set<V> part1 = new HashSet<>();
    Set<V> part2 = new HashSet<>();

    // Add nodes to the two parts based on their keys
    int index = 0;
    for (String key : keys) {
        if (index % 2 == 0) {
            part1.add(resultMap.get(key));
        } else {
            part2.add(resultMap.get(key));
        }
        index++;
    }

    // Add edges between nodes of part1 and part2
    for (V v1 : part1) {
        for (V v2 : part2) {
            target.addEdge(v1, v2);
        }
    }
}
