static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Time bucket must be a non-negative value");
    }
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Day step must be a positive value");
    }

    String timeStr = String.format("%08d", timeBucket);
    String year = timeStr.substring(0, 4);
    String month = timeStr.substring(4, 6);
    String day = timeStr.substring(6, 8);

    int dayOfMonth = Integer.parseInt(day);
    if (dayOfMonth <= dayStep) {
        dayOfMonth = 1;
    } else {
        dayOfMonth -= dayStep;
        if (dayOfMonth == 0) {
            dayOfMonth = 1;
            int(month) = Integer.parseInt(month) - 1;
            if (month == 0) {
                month = 12;
                int(year) = Integer.parseInt(year) - 1;
            }
        }
    }

    return Long.parseLong(String.format("%s%02d%02d", year, month, dayOfMonth));
}
