private void pop(final String descriptor) throws IllegalArgumentException {
    Stack<AbstractType> stack = getPositionalParametersStack();

    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    int count = 0;
    for (char c : descriptor.toCharArray()) {
        switch (c) {
            case 'I': case 'J': count++; break; // int, long
            case 'F': case 'D': count += 2; break; // float, double
            case 'L': case '[': // object or array
                count++;
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor character: " + c);
        }
    }

    while (count > 0 && !stack.isEmpty()) {
        stack.pop();
        count--;
    }
}
