/**
 * Writes the contents of the {@link LinkedBuffer} into the {@link DataOutput}.
 * @return the total content size of the buffer.
 */
public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new NullPointerException("DataOutput cannot be null");
    }
    if (node == null) {
        throw new NullPointerException("LinkedBuffer cannot be null");
    }
    int totalSize = 0;
    while (node != null) {
        out.write(node.getData(), 0, node.getLength());
        totalSize += node.getLength();
        node = node.getNext();
    }
    return totalSize;
}
