// Define a visitor pattern to traverse and remove nodes
class RemoveActiveVisitor implements CategoryVisitor {
    private int removedNodeCount = 0;

    @Override
    public void visit(Category node) {
        if (!node.isActive()) {
            // Remove the node from its parent
            node.getParent().removeChild(node);
            removedNodeCount++;
        } else {
            // Recursively visit child nodes
            for (Category child : node.getChildren()) {
                child.accept(this);
            }
        }
    }

    public int getRemovedNodeCount() {
        return removedNodeCount;
    }
}

// Define the Category class and necessary methods
class Category {
    private boolean active;
    private Category parent;
    private List<Category> children;

    public Category(boolean active) {
        this.active = active;
        this.parent = null;
        this.children = new ArrayList<>();
    }

    public boolean isActive() {
        return active;
    }

    public void setActive(boolean active) {
        this.active = active;
    }

    public Category getParent() {
        return parent;
    }

    public void setParent(Category parent) {
        this.parent = parent;
    }

    public List<Category> getChildren() {
        return children;
    }

    public void addChild(Category child) {
        child.setParent(this);
        children.add(child);
    }

    public void removeChild(Category child) {
        child.setParent(null);
        children.remove(child);
    }

    // Implement the Visitor pattern
    public void accept(CategoryVisitor visitor) {
        visitor.visit(this);
    }
}

// Define the Visitor interface
interface CategoryVisitor {
    void visit(Category node);
}
