protected int removeUnusedNodes(){
    // Assuming.CategoryTree is a class representing the category tree
    // and it has a method isActive() to check if a node is active
    // and a removeNode() method to remove a node from the tree

    if (categoryTree == null) {
        throw new IllegalArgumentException("Category tree cannot be null");
    }

    int removedCount = 0;

    Stack<CategoryNode> stack = new Stack<>();
    stack.push(categoryTree.getRoot());

    while (!stack.isEmpty()) {
        CategoryNode node = stack.pop();
        if (!node.isActive()) {
            categoryTree.removeNode(node);
            removedCount++;
        } else {
            for (CategoryNode child : node.getChildren()) {
                stack.push(child);
            }
        }
    }

    return removedCount;
}
