        throw new IllegalArgumentException("constantPoolEntryIndex must be non-negative");
    }
    if (charBuffer == null) {
        throw new IllegalArgumentException("charBuffer must not be null");
    }
    // Assuming classFileBuffer is a byte array containing the class file data
    if (constantPoolEntryIndex * 4 > classFileBuffer.length) {
        throw new IllegalArgumentException("constantPoolEntryIndex is out of bounds for the classFileBuffer");
    }

    // Read the length of the UTF-8 string
    int length = ((classFileBuffer[constantPoolEntryIndex * 4] & 0xFF) |
                   (classFileBuffer[constantPoolEntryIndex * 4 + 1] & 0xFF) << 8);

    // Ensure the charBuffer is large enough to hold the string
    if (length * 2 > charBuffer.length) {
        throw new IllegalArgumentException("charBuffer is not large enough to hold the UTF-8 string");
    }

    // Read the UTF-8 bytes and convert to char array
    for (int i = 0; i < length; i++) {
        charBuffer[i * 2] = (char) (classFileBuffer[constantPoolEntryIndex * 4 + 2 + i * 2] & 0xFF);
        charBuffer[i * 2 + 1] = (char) (classFileBuffer[constantPoolEntryIndex * 4 + 2 + i * 2 + 1] & 0xFF);
    }

    // Convert the char array to a String and return it
    return new String(charBuffer, 0, length * 2);
