private void refillBuffer() throws IOException {
    int bytesRead = input.read(bufferArray);
    if (bytesRead == -1) {
        throw new IOException("No more data available");
    }
    buffer.clear();
    buffer.addAll(Arrays.asList(Arrays.copyOf(bufferArray, bytesRead)));
}
