protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    if (tour.isEmpty()) {
        return graph.createPath();
    }

    V startVertex = null;
    for (E edge : tour) {
        if (startVertex == null) {
            startVertex = edge.getSource();
        }
        if (graph.findEdge(edge.getTarget(), startVertex) != null) {
            startVertex = edge.getTarget();
        }
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("No valid tour path found");
    }

    List<E> edges = new ArrayList<>(tour);
    edges.sort(Comparator.comparing((E e) -> startVertex.equals(graph.findEdge(e.getTarget(), startVertex) != null ? e.getTarget() : e.getSource())));

    GraphPath<V, E> path = graph.createWalk(startVertex, edges.stream().map(Graph::copyEdge).collect(Collectors.toList()), true);
    return path;
}
