protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input set and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return null; // Return null if the tour set is empty
    }

    V startVertex = null;
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (startVertex == null) {
            startVertex = source;
        } else {
            if (startVertex.equals(target)) {
                startVertex = target; // Update the start vertex to the current target if it matches
            }
        }
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("Invalid tour set: No matching vertices found");
    }

    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    for (E edge : edgeList) {
        V nextVertex = graph.getEdgeTarget(edge).equals(startVertex) ? graph.getEdgeSource(edge) : graph.getEdgeTarget(edge);
        if (vertexList.contains(nextVertex)) {
            throw new IllegalArgumentException("Invalid tour set: Cycle detected");
        }
        vertexList.add(nextVertex);
        startVertex = nextVertex;
    }

    return new GraphWalk<>(graph, vertexList, edgeList);
}
