protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    if (tour.isEmpty()) {
        return graph.createPath();
    }

    int size = tour.size();
    Iterator<E> edgeIterator = tour.iterator();
    E firstEdge = edgeIterator.next();
    V source = graph.getEdgeSource(firstEdge);
    V target = graph.getEdgeTarget(firstEdge);

    GraphPath<V,E> path = graph.createPath(source, target);

    for (int i = 0; i < size - 1; i++) {
        E edge = edgeIterator.next();
        target = graph.getEdgeTarget(edge);
        path = path.concat(graph.createPath(target, graph.getEdgeSource(edge)));
    }

    return path;
}
