private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    if (minLabel >= bucketsByLabel.size() || bucketsByLabel.get(minLabel).isEmpty()) {
        throw new NoSuchElementException("No non-empty bucket with the given label");
    }

    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    for (int vertex : minBucket) {
        if (vertex < 0 || vertex >= labels.size()) {
            throw new IllegalArgumentException("Invalid vertex label");
        }
        labels.set(vertex, 0);
    }

    bucketsByLabel.set(0, new HashSet<>(minBucket));
    bucketsByLabel.get(minLabel).clear();
}
