private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false; // Node cannot be null
    }

    if (node == head) {
        head = node.next;
        if (head != null) {
            head.prev = null;
        }
    } else if (node == tail) {
        tail = node.prev;
        if (tail != null) {
            tail.next = null;
        }
    } else {
        ListNodeImpl<E> prev = node.prev;
        ListNodeImpl<E> next = node.next;
        prev.next = next;
        next.prev = prev;
    }

    node.prev = null;
    node.next = null;
    size--;
    return true;
}
