private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("The bounds list cannot be null or empty");
    }

    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(n, 0));
    long totalSum = 0;

    for (int i = 0; i < n; i++) {
        totalSum += bounds.get(i);
        suffixSum.set(i, totalSum);
    }

    for (int i = 1; i < n; i++) {
        suffixSum.set(i, suffixSum.get(i) - suffixSum.get(i - 1));
    }

    return new Pair<>(suffixSum, totalSum);
}
```

