        java.lang.reflect.Method getterMethod = clazz.getMethod("get" + propertyName);
        java.lang.reflect.Method setterMethod = clazz.getMethod("set" + propertyName, getterMethod.getReturnType());
        return setterMethod != null;
    } catch (NoSuchMethodException e) {
        return false;
    }
}
