import java.util.ArrayList;
import java.util.List;

/**
 * Computes the global separator list of the  {@code graph}. More precisely, for every edge $e$ in the $G = (V, E)$ computes list of minimal separators $S_e$ in the neighborhood of $e$ and then concatenates these lists. Note: the result may contain duplicates
 * @return the list of minimal separators of every edge $e$ in the inspected graph
 */
private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<Integer, E> graph) {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    for (Edge<E> edge : graph.getEdges()) {
        Vertex<Integer> vertex1 = edge.getSource();
        Vertex<Integer> vertex2 = edge.getDestination();
        List<Pair<Integer, Integer>> localSeparatorList = findMinimalSeparators(vertex1, vertex2, graph);
        globalSeparatorList.add(new Pair<>(localSeparatorList, edge));
    }

    return globalSeparatorList;
}

/**
 * Finds the minimal separators in the neighborhood of the edge defined by two vertices
 * @param vertex1 the first vertex of the edge
 * @param vertex2 the second vertex of the edge
 * @param graph the graph containing the vertices and edges
 * @return the list of minimal separators
 */
private List<Pair<Integer, Integer>> findMinimalSeparators(Vertex<Integer> vertex1, Vertex<Integer> vertex2, Graph<Integer, E> graph) {
    List<Pair<Integer, Integer>> localSeparatorList = new ArrayList<>();

    // Get the neighbors of both vertices
    List<Vertex<Integer>> neighbors1 = graph.getNeighbors(vertex1);
    List<Vertex<Integer>> neighbors2 = graph.getNeighbors(vertex2);

    // Find the intersection of the neighbors (excluding the other vertex)
    for (Vertex<Integer> neighbor : neighbors1) {
        if (!neighbor.equals(vertex2) && neighbors2.contains(neighbor)) {
            localSeparatorList.add(new Pair<>(vertex1.getId(), neighbor.getId()));
        }
    }

    return localSeparatorList;
}
