private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList(Graph<Integer, E> graph) {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

    for (Edge<Integer, E> edge : graph.getEdges()) {
        int u = edge.getSource();
        int v = edge.getTarget();

        Set<Integer> neighborU = getNeighbors(graph, u);
        Set<Integer> neighborV = getNeighbors(graph, v);

        Set<Integer> union = new HashSet<>(neighborU);
        union.addAll(neighborV);

        Set<Integer> intersection = new HashSet<>(neighborU);
        intersection.retainAll(neighborV);

        List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();
        for (int node : union) {
            if (node != u && node != v && !intersection.contains(node)) {
                minimalSeparators.add(new Pair<>(node, u));
                minimalSeparators.add(new Pair<>(node, v));
            }
        }

        globalSeparatorList.add(new Pair<>(minimalSeparators, edge));
    }

    return globalSeparatorList;
}

private Set<Integer> getNeighbors(Graph<Integer, E> graph, int vertex) {
    Set<Integer> neighbors = new HashSet<>();
    for (Edge<Integer, E> edge : graph.getEdges()) {
        if (edge.getSource() == vertex) {
            neighbors.add(edge.getTarget());
        } else if (edge.getTarget() == vertex) {
            neighbors.add(edge.getSource());
        }
    }
    return neighbors;
}
