    public List<Pair<List<Pair<Integer,Integer>>, Integer>> computeGlobalSeparatorList(List<List<Integer>> graph, List<Integer> edges) {
        List<Pair<List<Pair<Integer,Integer>>, Integer>> globalSeparatorList = new ArrayList<>();

        for (int i = 0; i < edges.size(); i++) {
            int edge = edges.get(i);
            List<Pair<Integer,Integer>> separators = new ArrayList<>();
            for (int j = 0; j < graph.get(edge).size(); j++) {
                int neighbor = graph.get(edge).get(j);
                List<Pair<Integer, Integer>> neighborhood = new ArrayList<>();
                for (int k = 0; k < graph.get(neighbor).size(); k++) {
                    int neighborNeighbor = graph.get(neighbor).get(k);
                    if (neighborNeighbor != edge && !neighborhood.contains(new Pair<>(neighborNeighbor, neighbor))) {
                        neighborhood.add(new Pair<>(neighborNeighbor, neighbor));
                    }
                }
                Collections.sort(neighborhood, new Comparator<Pair<Integer, Integer>>() {
                    @Override
                    public int compare(Pair<Integer, Integer> o1, Pair<Integer, Integer> o2) {
                        if (!o1.getValue0().equals(o2.getValue0())) {
                            return o1.getValue0() - o2.getValue0();
                        } else {
                            return o1.getValue1() - o2.getValue1();
                        }
                    }
                });
                separators.add(new Pair<>(neighborhood, edge));
            }
            globalSeparatorList.add(new Pair<>(separators, edge));
        }

        return globalSeparatorList;
    }
}
